// Tip: type the bill in whole dollars, tap 10%, 15% or 20%; the tip and total show in whole dollars, rounded down.
// icon: line 17 7 7 17 dot 7 7 3 dot 17 17 3
state bill = "";
state pct = 15;

fn amount() -> int {
  return parse(bill, 0);
}

// Whole dollars: the division rounds toward zero, down for a positive bill.
fn tip() -> int {
  return amount() * pct / 100;
}

fn total() -> int {
  return amount() + tip();
}

label "Tip calculator";
row {
  input bill;
  button "10%" { pct = 10; }
  button "15%" { pct = 15; }
  button "20%" { pct = 20; }
}
label "Tip (" + pct + "%): $" + tip();
label "Total: $" + total();
