// Dice: press Roll to throw a six-sided die; its face (a square, one circle per pip) is drawn
// on the canvas and the number rolled shows beneath.
// icon: ring 12 12 9 dot 12 12 2
state roll = 0;                       // the face shown; 0 before the first roll

// The die: a silver square, then one circle per pip in the classic pattern.
