  rect(50, 30, 60, 60, 7);
  if roll == 1 || roll == 3 || roll == 5 { circle(80, 60, 5, 9); }
  if roll >= 2 { circle(65, 45, 5, 9); circle(95, 75, 5, 9); }
  if roll >= 4 { circle(95, 45, 5, 9); circle(65, 75, 5, 9); }
  if roll == 6 { circle(65, 60, 5, 9); circle(95, 60, 5, 9); }
  if roll == 0 { text("Roll the die", 80, 60, 8, 10); }
}

fn said() -> string {
  if roll == 0 { return "Dice"; }
  return "You rolled " + roll;
}

label "Dice";
canvas 160, 120, face();
label said();
button "Roll" { roll = 1 + random(6); }
