```app
// Traffic light: green 3 s, yellow 1 s, red 3 s, over and over; Pause stops it and starts it again.
// icon: loop 6 2 18 2 18 22 6 22 dot 12 6 3 dot 12 12 3 dot 12 18 3
state phase = 0;      // 0 green, 1 yellow, 2 red
state left = 3000;    // ms left in this phase
state speed = 100;    // ms a step; 0 while paused

fn dur(p: int) -> int {
  if p == 1 { return 1000; }
  return 3000;
}

// The color of lamp p: gray unless it is the one lit.
fn lamp(p: int) -> int {
  if p != phase { return 8; }
  if p == 0 { return 2; }
  if p == 1 { return 3; }
  return 1;
}

fn name() -> string {
  if phase == 0 { return "Green"; }
  if phase == 1 { return "Yellow"; }
  return "Red";
}

// The light, drawn anew from the states: a housing and three lamps, red over yellow over green.
fn scene() {
  rect(36, 4, 88, 232, 9);
  circle(80, 48, 36, lamp(2));
  circle(80, 120, 36, lamp(1));
  circle(80, 192, 36, lamp(0));
  text(name(), 80, 120, 10, 0);
}

every speed {
  left -= 100;
  if left <= 0 {
    phase = (phase + 1) % 3;
    left = dur(phase);
  }
}

label "Traffic light";
canvas 160, 240, scene();
row {
  button "Pause" {
    if speed == 0 {
      speed = 100;
    } else {
      speed = 0;
    }
  }
  label name() + "   " + left / 1000 + " s";
}
```

