// Rock Paper Scissors: tap Rock, Paper or Scissors; the computer picks at random and the score
// follows. Hands are drawn on the canvas.
// icon: loop 5 5 14 5 14 19 5 19 line 8 10 16 10 line 8 14 16 14 dot 19 19 3
state pick = 0;      // your hand: 0 none, 1 rock, 2 paper, 3 scissors
state cpick = 0;     // the computer's hand
state result = 0;    // 0 none, 1 win, 2 loss, 3 draw
state wins = 0;
state losses = 0;

fn name(i: int) -> string {
  if i == 1 { return "Rock"; }
  if i == 2 { return "Paper"; }
  return "Scissors";
}

// The hand as pixels, 6 a row: rock a boulder, paper a sheet with lines, scissors two blades.
fn hand(cells: list, at: int, kind: int) {
  if kind == 1 {
    cells[at + 8] = 8;
    cells[at + 9] = 8;
    cells[at + 14] = 8;
    cells[at + 15] = 8;
    cells[at + 16] = 8;
    cells[at + 20] = 8;
    cells[at + 21] = 8;
    cells[at + 22] = 8;
    cells[at + 23] = 8;
    cells[at + 26] = 8;
    cells[at + 27] = 8;
    cells[at + 28] = 8;
  } else if kind == 2 {
    for i in 0..4 { cells[at + 2 + i] = 7; }
    for i in 0..4 { cells[at + 8 + i] = 7; }
    for i in 0..4 { cells[at + 14 + i] = 7; }
    for i in 0..4 { cells[at + 20 + i] = 7; }
    for i in 0..4 { cells[at + 26 + i] = 7; }
    cells[at + 10] = 9;
    cells[at + 11] = 9;
    cells[at + 16] = 9;
    cells[at + 17] = 9;
    cells[at + 22] = 9;
    cells[at + 23] = 9;
  } else if kind == 3 {
    cells[at + 2] = 6;
    cells[at + 8] = 6;
    cells[at + 9] = 6;
    cells[at + 14] = 6;
    cells[at + 15] = 6;
    cells[at + 20] = 6;
    cells[at + 21] = 6;
    cells[at + 26] = 6;
    cells[at + 27] = 6;
    cells[at + 3] = 6;
    cells[at + 10] = 6;
    cells[at + 17] = 6;
    cells[at + 24] = 6;
    cells[at + 31] = 6;
  }
}

// Your hand on the left, the computer's on the right, and the verdict between.
fn scene() {
  let cells = [-1; 84];
  hand(cells, 2, pick);
  hand(cells, 10, cpick);
  pixels(cells, 0, 0, 6, 2);
  text("You", 8, 16, 6, 10);
  text("Computer", 32, 16, 6, 10);
  if result == 1 { text("You win", 20, 16, 6, 2); }
  if result == 2 { text("You lose", 20, 16, 6, 1); }
  if result == 3 { text("Draw", 20, 16, 6, 10); }
}

fn play(p: int) {
  let c = 1 + random(3);
  pick = p;
  cpick = c;
  if p == c {
    result = 3;
  } else if (p - c + 3) % 3 == 1 {
    result = 1;
    wins += 1;
  } else {
    result = 2;
    losses += 1;
  }
}

label "Rock Paper Scissors";
canvas 40, 6, scene();
row {
  button "Rock" { play(1); }
  button "Paper" { play(2); }
  button "Scissors" { play(3); }
}
label "Computer: " + name(cpick);
label "Wins " + wins + "   Losses " + losses;
