// Rock Paper Scissors: tap Rock, Paper or Scissors; the computer picks at random and the score
// follows. Hands are drawn on the canvas.
// icon: loop 5 5 14 5 14 19 5 19 line 8 10 16 10 line 8 14 16 14 dot 19 19 3
state pick = 0;      // your hand: 0 none, 1 rock, 2 paper, 3 scissors
state cpick = 0;     // the computer's hand
state result = 0;    // 0 none, 1 win, 2 loss, 3 draw
state wins = 0;
state losses = 0;

fn name(i: int) -> string {
  if i == 1 { return "Rock"; }
  if i == 2 { return "Paper"; }
  return "Scissors";
}

// The color of square i of a hand of a kind, -1 to show through: rock a boulder, paper a sheet
// with lines, scissors two blades. A function, for lists cannot be passed.
fn dot(i: int, kind: int) -> int {
  if kind == 1 {
    if i == 8 || i == 9 { return 8; }
    if i == 14 || i == 15 || i == 16 { return 8; }
    if i == 20 || i == 21 || i == 22 || i == 23 { return 8; }
    if i == 26 || i == 27 || i == 28 { return 8; }
  } else if kind == 2 {
    if i >= 2 && i <= 30 && i % 6 >= 2 && i % 6 <= 5 { return 7; }
    if i == 10 || i == 11 || i == 16 || i == 17 || i == 22 || i == 23 { return 9; }
  } else if kind == 3 {
    if i == 2 || i == 8 || i == 9 || i == 14 || i == 15 || i == 20 || i == 21 { return 6; }
    if i == 26 || i == 27 || i == 3 || i == 10 || i == 17 || i == 24 || i == 31 { return 6; }
  }
  return -1;
}

// Your hand on the left, the computer's on the right, and the verdict between.
fn scene() {
  let cells = [-1; 84];
  for i in 0..36 {
    let c = dot(i, pick);
    if c >= 0 { cells[2 + i] = c; }
    c = dot(i, cpick);
    if c >= 0 { cells[10 + i] = c; }
  }
  pixels(cells, 0, 0, 6, 2);
  text("You", 8, 16, 6, 10);
  text("Computer", 32, 16, 6, 10);
  if result == 1 { text("You win", 20, 16, 6, 2); }
  if result == 2 { text("You lose", 20, 16, 6, 1); }
  if result == 3 { text("Draw", 20, 16, 6, 10); }
}

fn play(p: int) {
  let c = 1 + random(3);
  pick = p;
  cpick = c;
  if p == c {
    result = 3;
  } else if (p - c + 3) % 3 == 1 {
    result = 1;
    wins += 1;
  } else {
    result = 2;
    losses += 1;
  }
}

label "Rock Paper Scissors";
canvas 40, 6, scene();
row {
  button "Rock" { play(1); }
  button "Paper" { play(2); }
  button "Scissors" { play(3); }
}
label "Computer: " + name(cpick);
label "Wins " + wins + "   Losses " + losses;
