```app
// Poll: tap Cats, Dogs or Birds to add a vote; the chart draws each bar twice as tall as its
// votes, standing on the baseline, its count above it.
// icon: line 3 20 21 20 line 6 20 6 12 line 12 20 12 7 line 18 20 18 10
state cats = 0;
state dogs = 0;
state birds = 0;

// The tallest bar may not run past the top: twice the votes while they fit, then all the bars
// scaled down together, so twice the votes is still twice as tall.
fn height(v: int) -> int {
  let m = max(max(cats, dogs), birds);
  if m == 0 { return 0; }
  if m * 2 <= 88 { return v * 2; }
  return v * 88 / m;
}

// One bar: a rect on the baseline, its count above it, its name below.
fn bar(v: int, x: int, color: int, name: string) {
  let h = height(v);
  rect(x, 110 - h, 30, h, color);
  text(v, x + 15, 106 - h, 8, 9);
  text(name, x + 15, 116, 6, 10);
}

fn scene() {
  rect(0, 110, 160, 2, 9);
  bar(cats, 15, 1, "Cats");
  bar(dogs, 65, 4, "Dogs");
  bar(birds, 115, 2, "Birds");
}

label "Poll";
canvas 160, 120, scene();
row {
  button "Cats" { cats += 1; }
  button "Dogs" { dogs += 1; }
  button "Birds" { birds += 1; }
}
