```app
// Tic-tac-toe for two on one device: tap an empty square to place X (first) or O; it says who
// won or Draw; New game empties the board.
// icon: line 2 7 10 15 line 10 7 2 15 ring 17 11 4
state board = [0; 9];   // 0 empty, 1 X, 2 O
state turn = 1;         // 1 X, 2 O
state over = false;
state result = "";

fn mark(v: int) -> int {
  if v == 1 { return 1; }
  return 4;
}

// The winner, 1 or 2, or 0 while the game is open.
fn winner() -> int {
  for r in 0..3 {
    let i = r * 3;
    if board[i] != 0 && board[i] == board[i + 1] && board[i] == board[i + 2] { return board[i]; }
  }
  for c in 0..3 {
    if board[c] != 0 && board[c] == board[c + 3] && board[c] == board[c + 6] { return board[c]; }
  }
  if board[4] != 0 {
    if board[0] == board[4] && board[4] == board[8] { return board[4]; }
    if board[2] == board[4] && board[4] == board[6] { return board[4]; }
  }
  return 0;
}

fn full() -> bool {
  for i in 0..9 {
    if board[i] == 0 { return false; }
  }
  return true;
}

fn place(i: int) {
  if over || board[i] != 0 { return; }
  board[i] = turn;
  let w = winner();
  if w != 0 {
    over = true;
    if w == 1 { result = "X wins"; } else { result = "O wins"; }
  } else if full() {
    over = true;
    result = "Draw";
  } else {
    turn = 3 - turn;
  }
}

// The board, 3 x 3 squares of 60 units, drawn anew from what the game remembers; the result
// below it once the game ends.
fn scene() {
  line(60, 4, 60, 176, 2, 8);
  line(120, 4, 120, 176, 2, 8);
  line(4, 60, 176, 60, 2, 8);
  line(4, 120, 176, 120, 2, 8);
  for i in 0..9 {
    let cx = (i % 3) * 60 + 30;
    let cy = (i / 3) * 60 + 30;
    if board[i] == 1 {
      line(cx - 17, cy - 17, cx + 17, cy + 17, 5, 1);
      line(cx - 17, cy + 17, cx + 17, cy - 17, 5, 1);
    } else if board[i] == 2 {
      ring(cx, cy, 18, 5, 4);
    }
  }
  if over { text(result, 90, 196, 12, 11); }
}

label "Tic-tac-toe";
canvas 180, 210, scene() { place((y / 60) * 3 + (x / 60)); }
row {
  button "New game" {
    clear(board);
    turn = 1;
    over = false;
    result = "";
  }
  if !over { label "X to play"; }
  if over { label result; }
}
