```app
// Connect four: tap a column to drop your disc, Red first then Yellow; four in a row wins.
// icon: ring 7 7 4 ring 17 7 4 ring 7 17 4 ring 17 17 4 line 4 12 20 12
state board = [0; 42];   // 7 columns of 6: 0 empty, 1 red, 3 yellow
state player = 1;        // the disc to drop: 1 red, 3 yellow
state win = 0;           // 0 while it plays, else who won
state full = false;

fn cell(c: int, r: int) -> int {
  if c < 0 || c > 6 || r < 0 || r > 5 { return 0; }
  return board[r * 7 + c];
}

// How many discs of one color run from a square along a way.
fn run(c: int, r: int, dc: int, dr: int) -> int {
  let v = board[r * 7 + c];
  let n = 0;
  for i in 1..4 {
    if cell(c + dc * i, r + dr * i) != v { return n; }
    n += 1;
  }
  return n;
}

fn won(c: int, r: int) -> bool {
  if run(c, r, 1, 0) + run(c, r, -1, 0) >= 3 { return true; }
  if run(c, r, 0, 1) + run(c, r, 0, -1) >= 3 { return true; }
  if run(c, r, 1, 1) + run(c, r, -1, -1) >= 3 { return true; }
  if run(c, r, 1, -1) + run(c, r, -1, 1) >= 3 { return true; }
  return false;
}

// The lowest row of a column that is empty, -1 if it is full.
fn lowest(c: int) -> int {
  for r in 0..6 {
    if cell(c, 5 - r) == 0 { return 5 - r; }
  }
  return -1;
}

fn drop(c: int) {
  if win != 0 { return; }
  let r = lowest(c);
  if r < 0 { return; }
  board[r * 7 + c] = player;
  if won(c, r) {
    win = player;
  } else {
    let n = 0;
    for i in 0..42 {
      if board[i] != 0 { n += 1; }
    }
    full = n == 42;
    player = 4 - player;
  }
}

fn newgame() {
  clear(board);
  player = 1;
  win = 0;
  full = false;
}

// The board: a blue frame with holes, the discs through them; the result over it.
fn scene() {
  rect(0, 0, 112, 96, 4);
  let cells = [-1; 42];
  for i in 0..42 { cells[i] = board[i]; }
  pixels(cells, 0, 0, 7, 16);
  if win == 1 { text("Red wins", 56, 48, 10, 9); }
  if win == 3 { text("Yellow wins", 56, 48, 10, 9); }
  if win == 0 && full { text("Draw", 56, 48, 10, 9); }
}

label "Connect four";
canvas 112, 96, scene() { drop(x / 16); }
row {
  button "New game" { newgame(); }
  if win == 0 && !full { label "Red to drop"; }
  if player == 3 && win == 0 && !full { label "Yellow to drop"; }
}
