// Pomodoro: 25:00 of work, then 5:00 of break, over and over. Start counts, Pause holds, Reset
// sets it back to work at 25:00.
// icon: ring 12 12 9 dot 12 12 2 line 12 12 12 7
state left = 1500;      // seconds left in the phase
state work = true;      // work now, break after
state running = false;

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

fn clock() -> string {
  return (left / 60) + ":" + two(left % 60);
}

fn total() -> int {
  if work { return 1500; }
  return 300;
}

fn phase() -> string {
  if work { return "Work"; }
  return "Break";
}

// The clock, its phase and the time left, drawn anew from the states.
fn scene() {
  if work {
    rect(10, 84, 140, 8, 8);
    rect(10, 84, 140 * left / total(), 8, 1);
  } else {
    rect(10, 84, 140, 8, 8);
    rect(10, 84, 140 * left / total(), 8, 2);
  }
  text(phase(), 80, 30, 10, 10);
  text(clock(), 80, 58, 20, 9);
  if !running { text("Paused", 80, 106, 8, 10); }
}

fn reset() {
  running = false;
  work = true;
  left = 1500;
}

every 1000 {
  if running {
    left -= 1;
    if left <= 0 {
      work = !work;          // work ends into break, break into work
      left = total();
    }
  }
}

label "Pomodoro";
canvas 160, 120, scene();
row {
  button "Start" { running = true; }
  button "Pause" { running = false; }
  button "Reset" { reset(); }
}
