// Clock: an analog face that starts at 12:00:00 and ticks each second, with the time as text.
// icon: ring 12 12 9 line 12 12 12 6 line 12 12 17 14 dot 12 12 1
state secs = 0;      // seconds since 12:00:00
state run = false;   // the timer runs only once started

fn two(n: int) -> string {
  if n < 10 { return "0" + n; }
  return "" + n;
}

// The time as text, 12 hours on the face.
fn say() -> string {
  let h = secs / 3600 % 12;
  if h == 0 { h = 12; }
  return h + ":" + two(secs / 60 % 60) + ":" + two(secs % 60);
}

// A hand: a line from the center at a degrees clockwise from the top, l long.
fn hand(a: int, l: int, w: int, c: int) {
  line(80, 56, 80 + l * sin(a) / 1000, 56 - l * cos(a) / 1000, w, c);
}

fn scene() {
  ring(80, 56, 50, 2, 9);
  for i in 0..12 {   // a dot at each hour
    circle(80 + 44 * sin(i * 30) / 1000, 56 - 44 * cos(i * 30) / 1000, 2, 10);
  }
  hand(secs / 3600 % 12 * 30 + secs / 60 % 60 / 2, 26, 3, 9);   // hour
  hand(secs / 60 % 60 * 6 + secs % 60 / 10, 38, 2, 9);          // minute
  hand(secs % 60 * 6, 44, 1, 1);                                // second
  circle(80, 56, 2, 9);
  text(say(), 80, 112, 8, 9);
}

every 1000 {
  if run { secs += 1; }
}

label "Clock";
canvas 160, 120, scene();
if !run { button "Start" { run = true; } }
```

```app
// Calculator: tap the buttons to type; = shows the result, C clears; / by zero shows Error.
// icon: line 4 3 4 21 line 4 12 9 12 line 14 3 14 8 line 19 3 14 8 line 14 8 14 13 line 14 13 19 13 line 14 13 14 21 line 14 21 19 21
state shown = "0";     // what the display reads
state acc = 0;         // the left side of a pending operation
state op = "";         // a pending + - * /
state fresh = true;    // the next digit starts a new number
state err = false;

fn clear_all() {
  shown = "0";
  acc = 0;
  op = "";
  fresh = true;
  err = false;
}

fn digit(d: int) {
  if err { clear_all(); }
  if fresh {
    shown = "" + d;
    fresh = false;
  } else if len(shown) < 15 {
    shown = shown + d;
  }
}

// One operation, as text; / rounds toward zero, and / by zero is Error.
fn apply(a: int, b: int, o: string) -> string {
  if o == "+" { return "" + (a + b); }
  if o == "-" { return "" + (a - b); }
  if o == "*" { return "" + (a * b); }
  if o == "/" {
    if b == 0 { return "Error"; }
    return "" + (a / b);
  }
  return "" + b;
}

// An operator: finish any pending one first, so 12 + 7 + shows 19.
fn operate(o: string) {
  if err { return; }
  if op != "" && !fresh {
    let r = apply(acc, parse(shown, 0), op);
    if r == "Error" { err = true; shown = "Error"; op = ""; fresh = true; return; }
    shown = r;
