// Minesweeper: tap to reveal, Flag toggles flagging; clear every safe square to win.
// icon: dot 8 8 3 dot 16 16 3 line 5 19 19 5 line 5 5 19 19
state mines = [0; 81];        // 1 where a mine is
state revealed = [false; 81];
state flagged = [false; 81];
state started = false;        // mines are placed after the first tap
state over = false;
state won = false;
state flagging = false;       // what a tap does

fn at(x: int, y: int) -> int { return y * 9 + x; }

// Mines touching (x, y), itself included: a mine's own count is 1.
fn touch(x: int, y: int) -> int {
  let n = 0;
  for yy in y - 1..y + 2 {
    for xx in x - 1..x + 2 {
      if xx >= 0 && xx < 9 && yy >= 0 && yy < 9 && mines[at(xx, yy)] == 1 { n += 1; }
    }
  }
  return n;
}

// Mines around the first square, none on it or touching it, so it opens a number.
fn place(keep: int) {
  clear(mines);
  for i in 0..81 { push(mines, 0); }
  let k = random(81);
  for j in 0..10 {
    let i = (k + j) % 81;
    let x = i % 9;
    let y = i / 9;
    if abs(x - keep % 9) <= 1 && abs(y - keep / 9) <= 1 { i = (i + 9) % 81; }
    mines[i] = 1;
  }
}

// Flood: reveal the square, and if it touches no mine, its neighbours too, without recursion.
fn reveal(first: int) {
  let stack = [0; 0];
  push(stack, first);
  repeat 729 {
    if len(stack) > 0 {
      let i = stack[len(stack) - 1];
      remove(stack, len(stack) - 1);
      if !revealed[i] && !flagged[i] {
        revealed[i] = true;
        if mines[i] == 0 && touch(i % 9, i / 9) == 0 {
          let x = i % 9;
          let y = i / 9;
          for yy in y - 1..y + 2 {
            for xx in x - 1..x + 2 {
              if xx >= 0 && xx < 9 && yy >= 0 && yy < 9 { push(stack, at(xx, yy)); }
            }
          }
        }
      }
    }
  }
}

// Every safe square revealed?
fn cleared() -> bool {
  for i in 0..81 {
    if mines[i] == 0 && !revealed[i] { return false; }
  }
  return true;
}

fn tap(i: int) {
  if over || flagged[i] || revealed[i] { return; }
  if !started {
    place(i);
    started = true;
  }
  if mines[i] == 1 {
    revealed[i] = true;
    over = true;
  } else {
    reveal(i);
    if cleared() { over = true; won = true; }
  }
}

// The board as squares: hidden dim, flags marked, numbers by their count, mines red.
fn cell(i: int) -> int {
  if !revealed[i] { return 8; }
  if mines[i] == 1 { return 1; }
  let n = touch(i % 9, i / 9);
  if n == 0 { return 0; }
  if n == 1 { return 6; }
  if n == 2 { return 2; }
  return 4;
}

fn scene() {
  let cells = [0; 81];
  for i in 0..81 { cells[i] = cell(i); }
  pixels(cells, 0, 0, 9, 12);
