  for i in 0..81 { push(mines, 0); }
  clear(revealed);
  for i in 0..81 { push(revealed, false); }
  clear(flagged);
  for i in 0..81 { push(flagged, false); }
  started = false;
  over = false;
  won = false;
}

start();

label "Minesweeper";
row {
