// 2048: the arrow keys or the Up, Down, Left, Right buttons slide the tiles; equal tiles merge;
// reach no move and it is over. Score above the board.
// icon: fill 4 4 20 4 20 20 4 20 line 9 9 15 15 line 15 9 9 15
state b = [0; 16];          // the board: 0 an empty square, else the tile's number
state score = 0;
saved state best = 0;
state over = false;
state started = false;

fn at(x: int, y: int) -> int { return y * 4 + x; }

// The square p steps from the edge the tiles slide toward, on line v, moving in direction d:
// 0 left, 1 right, 2 up, 3 down.
fn sq(d: int, v: int, p: int) -> int {
  if d == 0 { return at(p, v); }
  if d == 1 { return at(3 - p, v); }
  if d == 2 { return at(v, p); }
  return at(v, 3 - p);
}

// One line of the board: slide it, merge equal neighbours once, slide again.
// Returns whether the line changed.
fn line(d: int, v: int) -> bool {
  let t = [0; 4];
  let n = 0;
  for p in 0..4 {
    let k = b[sq(d, v, p)];
    if k > 0 { t[n] = k; n += 1; }
  }
  for i in 0..n - 1 {
    if t[i] == t[i + 1] {
      t[i] += t[i];
      t[i + 1] = 0;
      score += t[i];
      i += 1;
    }
  }
  let m = 0;
  let changed = false;
  for p in 0..4 {
    let k = 0;
    if m < n { k = t[m]; m += 1; }
    if b[sq(d, v, p)] != k { changed = true; }
    b[sq(d, v, p)] = k;
  }
  return changed;
}

fn move(d: int) {
  if over || !started { return; }
  let changed = false;
  for v in 0..4 {
    if line(d, v) { changed = true; }
  }
  if changed { spawn(); }
  if !canmove() {
    over = true;
    best = max(best, score);
  }
}

// A 2, or now and then a 4, on a square taken from the empty ones.
fn spawn() {
  let free = [0; 0];
  for i in 0..16 {
    if b[i] == 0 { push(free, i); }
  }
  if len(free) > 0 {
    b[free[random(len(free))]] = 2 + 2 * random(5) / 4;
  }
}

fn start() {
  clear(b);
  score = 0;
  over = false;
  started = true;
  spawn();
  spawn();
}

