// Each shape and turn as a 4x4 pattern: bit y*4+x set means a square.
fn pat(t: int, r: int) -> int {
  if t == 0 { if r == 1 || r == 3 { return 4369; } return 240; }
  if t == 1 { return 51; }
  if t == 2 { if r == 0 { return 60; } if r == 1 { return 1080; } if r == 2 { return 864; } return 135; }
  if t == 3 { if r == 0 { return 30; } if r == 1 { return 624; } if r == 2 { return 108; } return 75; }
  if t == 4 { if r == 0 { return 36; } if r == 1 { return 802; } if r == 2 { return 18; } return 520; }
  if t == 5 { if r == 0 { return 576; } if r == 1 { return 306; } if r == 2 { return 39; } return 612; }
  if r == 0 { return 1586; } if r == 1 { return 113; } if r == 2 { return 1552; } return 561;
}

fn bitat(t: int, r: int, gx: int, gy: int) -> bool {
  let p = pat(t, r);
  let n = gy * 4 + gx;
  for i in 0..n { p /= 2; }
